-- Reprocessing a record whose latest job received a provider response cut at
-- its output limit (response.status='incomplete') creates a new job instead of
-- reusing it. Reusing would replay the stored, unparseable response (or reject
-- a new request version), so the record could never be analysed again. The old
-- job keeps its receipt, usage and budget rows; nothing is deleted or resent.
-- Everything else in begin_record_operation is unchanged from production.
CREATE OR REPLACE FUNCTION public.begin_record_operation(p_record uuid, p_operation text, p_executor text DEFAULT 'local'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
      declare
        j pipeline_jobs;
          prior uuid;
            run uuid;
              attempt uuid;
                task uuid;
                  old_task uuid;
                    kind text;
                      source source_records;
                        new_job boolean:=false;
                        begin
                          if p_operation not in ('prepare','enrich','match','process','ocr')
                              or p_executor not in ('local','vercel_workflow') then
                                  raise exception 'INVALID_OPERATION';
                                    end if;

                                      select * into strict source from source_records where id=p_record for update;

  -- A transaction snapshot predating the locks could hide a prior pause.
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'PROVIDER_SCOPE_ISOLATION_UNSUPPORTED';end if;
  -- The source lock fences job inserts; job and run locks fence task inserts;
  -- task/job locks fence FK-checked receipt inserts. Existing rows are locked
  -- explicitly against update or delete. All locks last only this DB call.
  perform 1 from public.pipeline_jobs pj_guard where pj_guard.source_record_id=p_record order by pj_guard.id for update nowait;
  perform 1 from public.pipeline_runs r where r.id in (select pj_guard.run_id from public.pipeline_jobs pj_guard where pj_guard.source_record_id=p_record) order by r.id for update nowait;
  perform 1 from public.worker_tasks t where t.source_record_id=p_record
    or t.pipeline_job_id in (select pj_guard.id from public.pipeline_jobs pj_guard where pj_guard.source_record_id=p_record)
    or t.run_id in (select pj_guard.run_id from public.pipeline_jobs pj_guard where pj_guard.source_record_id=p_record)
    order by t.id for update nowait;
  perform 1 from public.cloud_checkpoints c where c.task_id in (
    select t.id from public.worker_tasks t where t.source_record_id=p_record
      or t.pipeline_job_id in (select pj_guard.id from public.pipeline_jobs pj_guard where pj_guard.source_record_id=p_record)
      or t.run_id in (select pj_guard.run_id from public.pipeline_jobs pj_guard where pj_guard.source_record_id=p_record)
    ) order by c.task_id,c.item_key for update nowait;
  perform 1 from public.provider_calls pc where pc.pipeline_job_id in
    (select pj_guard.id from public.pipeline_jobs pj_guard where pj_guard.source_record_id=p_record)
    order by pc.id for update nowait;
  if exists(select 1 from public.worker_tasks t where t.failure_kind='provider_unknown' and
    (t.source_record_id=p_record
      or t.pipeline_job_id in (select pj_guard.id from public.pipeline_jobs pj_guard where pj_guard.source_record_id=p_record)
      or t.run_id in (select pj_guard.run_id from public.pipeline_jobs pj_guard where pj_guard.source_record_id=p_record)))
    or exists(select 1 from public.cloud_checkpoints c join public.worker_tasks t on t.id=c.task_id
    where (t.source_record_id=p_record
      or t.pipeline_job_id in (select pj_guard.id from public.pipeline_jobs pj_guard where pj_guard.source_record_id=p_record)
      or t.run_id in (select pj_guard.run_id from public.pipeline_jobs pj_guard where pj_guard.source_record_id=p_record))
      and c.item_key like 'ai:%' and c.value->>'state' in ('sending','unknown'))
    or exists(select 1 from public.provider_calls pc join public.pipeline_jobs pj_guard on pj_guard.id=pc.pipeline_job_id
      where pj_guard.source_record_id=p_record and pc.state='sending') then raise exception 'PROVIDER_UNKNOWN';end if;
  if exists(select 1 from public.worker_tasks t where t.failure_kind='provider_reconciliation' and
    (t.source_record_id=p_record
      or t.pipeline_job_id in (select pj_guard.id from public.pipeline_jobs pj_guard where pj_guard.source_record_id=p_record)
      or t.run_id in (select pj_guard.run_id from public.pipeline_jobs pj_guard where pj_guard.source_record_id=p_record))) then
    raise exception 'PROVIDER_RECONCILIATION_REQUIRED';
  end if;

                                        select * into j from pipeline_jobs where source_record_id=p_record order by created_at desc,id desc limit 1 for update;

                                          if exists(
                                              select 1 from worker_tasks t
                                                  where (t.source_record_id=p_record or t.run_id in(select run_id from pipeline_jobs where source_record_id=p_record))
                                                        and (t.status in ('queued','running') or t.lease_until>now())
                                                          ) then raise exception 'ACTIVE_TASK'; end if;

                                                            if exists(select 1 from provider_calls where pipeline_job_id in(select id from pipeline_jobs where source_record_id=p_record) and state='sending')
                                                                or exists(
                                                                      select 1 from cloud_checkpoints c
                                                                            join worker_tasks t on t.id=c.task_id
                                                                                  where c.value->>'state'='sending'
                                                                                          and (t.source_record_id=p_record or exists(select 1 from pipeline_jobs x where x.source_record_id=p_record and position(x.id::text in c.item_key)>0))
                                                                                              ) then raise exception 'PROVIDER_UNKNOWN'; end if;

                                                                                                if p_operation='match' and (source.evidence_status<>'ready' or source.enrichment_status<>'completed') then raise exception 'PREPARE_AND_ENRICH_FIRST'; end if;
                                                                                                  if p_operation='enrich' and source.evidence_status<>'ready' then raise exception 'PREPARE_FIRST'; end if;

                                                                                                    prior:=j.id;
                                                                                                      if j.id is null
                                                                                                          or exists(select 1 from analysis_results where pipeline_job_id=j.id)
                                                                                                              or exists(select 1 from matching_candidates where pipeline_job_id=j.id)
                                                                                                                  or exists(select 1 from review_decisions where pipeline_job_id=j.id)
    -- A provider response cut at its output limit can never be parsed, and reusing
    -- the job would replay it. Start a new job; the old one keeps its receipt.
    or exists(select 1 from cloud_checkpoints c where left(c.item_key,40)='ai:'||j.id::text||':'
     and c.value->>'state'='received' and c.value#>>'{response,status}'='incomplete') then
                                                                                                                      insert into pipeline_runs(status,stage,selected_count,parameters)
                                                                                                                          values('queued','preparation',1,jsonb_build_object(
                                                                                                                                'auto_process',p_operation in ('process','ocr'),
                                                                                                                                      'purpose','record_operation',
                                                                                                                                            'operation',p_operation,
                                                                                                                                                  'ocr_recovery',p_operation='ocr'
                                                                                                                                                      )) returning id into run;

                                                                                                                                                          insert into pipeline_jobs(run_id,source_record_id,previous_job_id,status,preparation_status,enrichment_status)
                                                                                                                                                              values(
                                                                                                                                                                    run,
                                                                                                                                                                          p_record,
                                                                                                                                                                                prior,
                                                                                                                                                                                      case when p_operation in ('match','enrich') then 'ready' else 'selected' end,
                                                                                                                                                                                            case
                                                                                                                                                                                                    when p_operation in ('prepare','process','ocr') then 'pending'
                                                                                                                                                                                                            when source.evidence_status='ready' then 'ready'
                                                                                                                                                                                                                    else 'pending'
                                                                                                                                                                                                                          end,
                                                                                                                                                                                                                                case when p_operation='match' then 'completed' else 'pending' end
                                                                                                                                                                                                                                    ) returning * into j;
                                                                                                                                                                                                                                        new_job:=true;
                                                                                                                                                                                                                                          else
                                                                                                                                                                                                                                              run:=j.run_id;
                                                                                                                                                                                                                                                  perform capture_job_snapshot(j.id,'before_recovery');
                                                                                                                                                                                                                                                      update job_attempts
                                                                                                                                                                                                                                                          set status=case when status='running' then 'interrupted' else status end,
                                                                                                                                                                                                                                                                  completed_at=coalesce(completed_at,now())
                                                                                                                                                                                                                                                                      where pipeline_job_id=j.id;
                                                                                                                                                                                                                                                                          insert into job_attempts(pipeline_job_id,ordinal,operation)
                                                                                                                                                                                                                                                                              select j.id,coalesce(max(ordinal),0)+1,p_operation from job_attempts where pipeline_job_id=j.id
                                                                                                                                                                                                                                                                                  returning id into attempt;
                                                                                                                                                                                                                                                                                      update pipeline_jobs
                                                                                                                                                                                                                                                                                          set status=case when p_operation in ('match','enrich') then 'ready' else 'selected' end,
                                                                                                                                                                                                                                                                                                  error_message=null,
                                                                                                                                                                                                                                                                                                          completed_at=null,
                                                                                                                                                                                                                                                                                                                  claimed_at=null,
                                                                                                                                                                                                                                                                                                                          preparation_status=case when p_operation in ('prepare','process','ocr') then 'pending' else preparation_status end
                                                                                                                                                                                                                                                                                                                              where id=j.id;
                                                                                                                                                                                                                                                                                                                                  update pipeline_runs
                                                                                                                                                                                                                                                                                                                                      set status='queued',
                                                                                                                                                                                                                                                                                                                                              stage=case when p_operation='match' then 'matching' when p_operation='enrich' then 'enrichment' else 'preparation' end,
                                                                                                                                                                                                                                                                                                                                                      completed_at=null,
                                                                                                                                                                                                                                                                                                                                                              processing_completed_at=null,
                                                                                                                                                                                                                                                                                                                                                                      parameters=parameters||jsonb_build_object('auto_process',p_operation in ('process','ocr'),'ocr_recovery',p_operation='ocr')
                                                                                                                                                                                                                                                                                                                                                                          where id=run;
                                                                                                                                                                                                                                                                                                                                                                            end if;

                                                                                                                                                                                                                                                                                                                                                                              if attempt is null then
                                                                                                                                                                                                                                                                                                                                                                                  select id into attempt from job_attempts where pipeline_job_id=j.id order by ordinal desc limit 1;
                                                                                                                                                                                                                                                                                                                                                                                    end if;

                                                                                                                                                                                                                                                                                                                                                                                      kind:=case p_operation
                                                                                                                                                                                                                                                                                                                                                                                          when 'prepare' then 'prepare_run'
                                                                                                                                                                                                                                                                                                                                                                                              when 'enrich' then 'enrich_record'
                                                                                                                                                                                                                                                                                                                                                                                                  when 'match' then 'match_run'
                                                                                                                                                                                                                                                                                                                                                                                                      else 'process_run'
                                                                                                                                                                                                                                                                                                                                                                                                        end;

                                                                                                                                                                                                                                                                                                                                                                                                          select id into old_task
                                                                                                                                                                                                                                                                                                                                                                                                            from worker_tasks
                                                                                                                                                                                                                                                                                                                                                                                                              where executor=p_executor and (run_id=run or source_record_id=p_record)
                                                                                                                                                                                                                                                                                                                                                                                                                order by created_at desc,id desc limit 1;

                                                                                                                                                                                                                                                                                                                                                                                                                  insert into worker_tasks(task_type,run_id,source_record_id,pipeline_job_id,executor)
                                                                                                                                                                                                                                                                                                                                                                                                                    values(kind,case when kind='enrich_record' then null else run end,case when kind='enrich_record' then p_record else null end,j.id,p_executor)
                                                                                                                                                                                                                                                                                                                                                                                                                      returning id into task;

                                                                                                                                                                                                                                                                                                                                                                                                                        if not new_job and old_task is not null then
                                                                                                                                                                                                                                                                                                                                                                                                                            insert into cloud_checkpoints(task_id,item_key,value)
                                                                                                                                                                                                                                                                                                                                                                                                                                select task,item_key,value from cloud_checkpoints
                                                                                                                                                                                                                                                                                                                                                                                                                                    where task_id=old_task
                                                                                                                                                                                                                                                                                                                                                                                                                                          and (position(j.id::text in item_key)>0 or exists(select 1 from source_documents d where d.source_record_id=p_record and position(d.id::text in item_key)>0))
                                                                                                                                                                                                                                                                                                                                                                                                                                                and item_key not like '%:complete'
                                                                                                                                                                                                                                                                                                                                                                                                                                                      and item_key not like '%:discovered'
                                                                                                                                                                                                                                                                                                                                                                                                                                                            and item_key not like 'document_failed:%'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                on conflict do nothing;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    insert into cloud_budget_reservations(task_id,item_key,reserved_usd,actual_usd)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        select task,item_key,0,0 from cloud_budget_reservations
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            where task_id=old_task and position(j.id::text in item_key)>0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                on conflict do nothing;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if p_executor='vercel_workflow' and exists(
    select 1 from public.cloud_checkpoints c join public.worker_tasks prior_task on prior_task.id=c.task_id
    where c.item_key like 'ocr:%' and (prior_task.source_record_id=p_record or prior_task.run_id in
      (select pj.run_id from public.pipeline_jobs pj where pj.source_record_id=p_record))
  ) then
    insert into public.cloud_checkpoints(task_id,item_key,value)
    select task,'legacy-ocr-pending:'||d.id::text,jsonb_build_object('version','legacy-ocr-pending-v1')
    from public.source_documents d where d.source_record_id=p_record
    on conflict(task_id,item_key) do nothing;
  end if;
  update source_records
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      set processing_status=case when p_operation='match' then 'processant'::processing_status else 'preparant'::processing_status end,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            evidence_status=case when p_operation in ('prepare','process','ocr') then 'pending' else evidence_status end,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  evidence_error=case when p_operation in ('prepare','process','ocr') then null else evidence_error end,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        enrichment_status=case when p_operation in ('enrich','process','ocr') then 'pending' else enrichment_status end,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              updated_at=now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                where id=p_record;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return jsonb_build_object('runId',run,'jobId',j.id,'taskId',task,'attemptId',attempt,'newJob',new_job);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  $function$;
